import itertools
from collections import defaultdict, deque

def check_girth(edges, n, min_girth=5):
    """Check if graph has girth >= min_girth"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    # Found a cycle
                    cycle_len = dist[node] + dist[neighbor] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = {colors[u] for u in adj[v] if colors[u] != -1}
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

